package com.via.himalaya.domain.model

import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable

/**
 * A trek's routes file, generated by scripts/build_routes.py and served from R2 at
 * trek_routes/<id>.json. It replaces the coordinate file: every way through the
 * trek's network, cut into sections at each junction and dead end.
 *
 * Nothing in it says which sections are alternatives or side trips. That depends
 * on which route is showing - once Hargaon is chosen on Kedarkantha, the Juda ka
 * Talab way becomes the alternative - so [RouteNetwork] works it out from where a
 * section starts and ends.
 */
@Serializable
data class TrekRoutes(
    @SerialName("trek_id")
    val trekId: String,
    /** When the file was generated; mirrors treks.routes_updated_at. */
    @SerialName("generated_at")
    val generatedAt: String? = null,
    @SerialName("osm_timestamp")
    val osmTimestamp: String? = null,
    val nodes: List<RouteNode> = emptyList(),
    val sections: List<RouteSection> = emptyList(),
    /** The default route, as section ids in walking order. */
    @SerialName("default")
    val defaultRoute: List<String> = emptyList(),
    /**
     * Every POI of the trek: what it is, and where it sits on the sections. The
     * app reads POIs from here alone; the separate POI file on R2 is kept only
     * for app versions from before routes.
     */
    val pois: List<RoutePoi> = emptyList()
)

/** A junction, a dead end, or the start or end of the default route. */
@Serializable
data class RouteNode(
    val id: String,
    val lon: Double,
    val lat: Double,
    val name: String? = null
)

/** The trail between two nodes. Coordinates run from [from] to [to]. */
@Serializable
data class RouteSection(
    val id: String,
    val from: String,
    val to: String,
    val km: Double,
    @SerialName("climb_m")
    val climbM: Int = 0,
    @SerialName("descent_m")
    val descentM: Int = 0,
    /** [lon, lat] pairs, as in GeoJSON. */
    val coords: List<List<Double>> = emptyList(),
    /** Every 100 m: [lat, lon, metres, km from this section's start]. */
    val profile: List<List<Double>> = emptyList(),
    /** Hand-written remark, e.g. that a path is only open in summer. */
    val note: String? = null
)

/**
 * One POI. The same fields as the POI file's records (see TrekPoi), except that
 * its position is a place on a section - [section], [atKm] into it, [offsetM] off
 * it - instead of a distance along one fixed line.
 */
@Serializable
data class RoutePoi(
    /** OSM identifier, e.g. "node/9117107250". */
    val id: String? = null,
    /** One of PoiCategory. */
    val category: String,
    /** Raw OSM value: ford, spring, camp_site, village... */
    val type: String,
    val name: String? = null,
    val lat: Double,
    val lon: Double,
    /** The section it is nearest to. */
    val section: String,
    /** How far into that section, from its `from` node. */
    @SerialName("at_km")
    val atKm: Double,
    /** How far off that section. */
    @SerialName("offset_m")
    val offsetM: Int,
    /** "start" or "end" when it sits beyond the trailhead rather than on the walk. */
    @SerialName("off_route")
    val offRoute: String? = null,
    @SerialName("ele_m")
    val eleM: Double? = null,
    @SerialName("approx_center")
    val approxCenter: Boolean = false,
    @SerialName("occupancy_rank")
    val occupancyRank: Int? = null,
    val tags: Map<String, String> = emptyMap()
)
